    43	pub fn encode(
    44	    writer: *std.Io.Writer,
    45	    style: Style,
    46	    size: Size,
    47	) std.Io.Writer.Error!void {
    48	    switch (style) {
    49	        .mode_2048 => try writer.print(
    50	            "\x1B[48;{};{};{};{}t",
    51	            .{
    52	                size.rows,
    53	                size.columns,
    54	                heightPixels(size),
    55	                widthPixels(size),
    56	            },
    57	        ),
    58	
    59	        .csi_14_t => try writer.print(
    60	            "\x1b[4;{};{}t",
    61	            .{
    62	                heightPixels(size),
    63	                widthPixels(size),
    64	            },
    65	        ),
    66	
    67	        .csi_16_t => try writer.print(
    68	            "\x1b[6;{};{}t",
    69	            .{
    70	                size.cell_height,
    71	                size.cell_width,
    72	            },
    73	        ),
    74	
    75	        .csi_18_t => try writer.print(
    76	            "\x1b[8;{};{}t",
    77	            .{
    78	                size.rows,
    79	                size.columns,
    80	            },
    81	        ),
    82	
